<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table id="tabelaAcos" class="table table-hover table-striped align-middle w-100"><thead><tr><th>Código</th><th>Descrição</th><th>Grupo</th><th>Especial</th><th>Peso líquido</th><th>Espessura</th><th>Ativo</th><th class="text-end">Ações</th></tr><tr class="filters"><th><input class="form-control form-control-sm" placeholder="Filtrar"></th><th><input class="form-control form-control-sm" placeholder="Filtrar"></th><th><input class="form-control form-control-sm" placeholder="Filtrar"></th><th><select class="form-select form-select-sm"><option value="">Todos</option><option>Sim</option><option>Não</option></select></th><th><input class="form-control form-control-sm"></th><th><input class="form-control form-control-sm"></th><th><select class="form-select form-select-sm"><option value="">Todos</option><option>Sim</option><option>Não</option></select></th><th></th></tr></thead><tbody><?php foreach($registros as $r): ?><tr><td><?=$e($r['codigo'])?></td><td><?=$e($r['descricao'])?></td><td><?=$e($r['grupo'])?></td><td><?=$r['especial']?'Sim':'Não'?></td><td data-order="<?=$e($r['peso_liquido'])?>"><?=number_format((float)$r['peso_liquido'],6,',','.')?></td><td data-order="<?=$e($r['espessura'])?>"><?=number_format((float)$r['espessura'],2,',','.')?></td><td data-order="<?=$r['ativo']?>"><?=$r['ativo']?'<span class="badge text-bg-success">Sim</span>':'<span class="badge text-bg-secondary">Não</span>'?></td><td class="text-end text-nowrap"><button class="btn btn-sm btn-outline-primary" onclick='editarAco(<?=json_encode($r,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>)'><i class="bi bi-pencil"></i></button> <form method="post" class="d-inline" onsubmit="return confirmarExclusaoAco();"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?=$e($r['id'])?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>